def _imp(w):
    core = w.rstrip(',.:;!')
    tail = w[len(core):]
    low = core.lower()
    if low in _EXCL: inf = _EXCL[low]
    else:
        inf = None
        for suf, outs in _RULES:
            if low.endswith(suf) and len(low) > len(suf) + 2:
                base = low[: -len(suf)]
                cands = [base + o for o in outs]
                if suf in ('йте', 'йтесь'):
                    cands = [base[:-1] + o for o in ('ыть', 'ить', 'ать', 'еть')] + cands
                inf = next((c for c in cands if c in _VOC), None)
                if inf is None: _UNK.add(core)
                break
        if inf is None: return w
    if core[0].isupper(): inf = inf[0].upper() + inf[1:]
    return inf + tail
