def fix(s):
    s = s.strip().rstrip('.')
    ws = s.split(' ')
    ws = [_IMP2.get(w, _IMP.get(w, _imp(w) if w[:1].isalpha() and w.lower().rstrip(',.:;') not in _NOTIMP else w)) for i, w in enumerate(ws)]
