    for a, b in _VY: s = _re.sub(a, b, s)
    s = s.replace('ты хотите', 'хочешь').replace(' хотите ', ' хочешь ').replace(' хотите', ' хочешь').replace('пытаетесь', 'пытаешься').replace('покупаете', 'покупаешь').replace('Украсть', 'Украсить').replace('который хотите', 'который нужно').replace('Если сушите', 'Если сушить')
    if s: s = s[0].upper() + s[1:]
    s = s.replace(' — ', ', ').replace(' - ', ', ')
    return s
